 private function renderDocumentCreateForm($table = null, $table_id = null)
 {
 if (auth()->user()->type == 'integrator')
 return redirect('/documents');

 $cash = Cash::where([['user_id', auth()->user()->id], ['state', true]])->first();

 if (!$cash) {
 if (!$this->userCanAccessCash()) {
