 }
 return redirect()->route('tenant.cash.index', ['redirect_reason' => 'no_cash_document']);
 }

 $configuration = Configuration::first();
 $is_contingency = 0;

 return view('tenant.documents.form', compact('is_contingency', 'configuration', 'table', 'table_id'));
 }

