 public function getFullDescription($row, $warehouse)
 {

 $desc = ($row->internal_id) ? $row->internal_id . ' - ' . $row->description : $row->description;
 $category = ($row->category) ? "{$row->category->name}" : "";
 $brand = ($row->brand) ? "{$row->brand->name}" : "";


 if ($row->unit_type_id != 'SERV') {
 if (isset($row['stock'])) {
 $warehouse_stock = number_format($row['stock'], 2);
 } else {
 $warehouse_stock = ($row->warehouses && $warehouse) ?
 number_format($row->warehouses->where('warehouse_id', $warehouse->id)->first()->stock, 2) :
 0;
 }

 $stock = ($row->warehouses && $warehouse) ? "{$warehouse_stock}" : "";
 } else {
 $stock = '';
 }

 $desc = "{$desc} - {$brand}";

 return [
 'full_description' => $desc,
 'brand' => $brand,
 'category' => $category,
 'stock' => $stock,
 'warehouse_description' => $warehouse->description,
 ];
 }


 public function record($id)
 {
 $this->forgetLegacyDocumentDetailCache($id);

 $document = Document::with([
 'items',
 'payments.payment_method_type',
 'payments.global_payment',
 'payments.payment_file',
 'state_type',
 'document_type',
 'user',
 'seller',
 'person.identity_document_type',
 ])->findOrFail($id);

 DocumentFiscalController::authorizeDocument($document);
 return new DocumentResource($document);
 }

 /**
 * Elimina claves de caché obsoletas del detalle (respuestas serializadas sin ítems).
 */
 protected function forgetLegacyDocumentDetailCache($id): void
 {
 foreach ([
 "document_detail_{$id}",
 "document_detail_v2_{$id}",
 "document_detail_v3_{$id}",
 ] as $cacheKey) {
 CacheHelper::forget(['document_detail'], $cacheKey);
 }
 }


 /**
 *
 * Generar cpe
 *
 * @param DocumentRequest $request
 * @return array
 */
 public function store(DocumentRequest $request)
 {
 return $this->storeForChannel($request, true);
 }

 public function storeFromHotelCheckout(DocumentRequest $request)
 {
 return $this->storeForChannel($request, true, true);
 }

 // ######## INICIO PERSISTENCIA FISCAL VENEZUELA ########
 public function storeFromSubscription(DocumentRequest $request)
 {
 return $this->storeForChannel($request, false);
 }

 private function storeForChannel(DocumentRequest $request, bool $webDocuments, bool $deferPdfUntilCommit = false)
 // ######## FIN PERSISTENCIA FISCAL VENEZUELA ########
 {
 try
 {
 // Validar restricciones de plan ANTES de crear el documento
 $exceed_limit = (new DocumentHelper)->exceedLimitDocuments();
 if($exceed_limit['success']) {
 return [
 'success' => false,
 'message' => $exceed_limit['message']
 ];
 }
 $validate = $this->validateDocument($request);
 if (!$validate['success']) return $validate;

 if(!$this->validationOpenCash($request)) return $this->generalResponse(false, 'Ocurrió un error: Caja seleccionada en métodos de pago se encuentra cerrada');


 $data = $request->all();
 if (empty($data['source_module'])) {
 $data['source_module'] = 'WEB';
 }

 $res = $this->storeWithData($data, $webDocuments, $deferPdfUntilCommit);
 $document_id = $res['data']['id'];
 $this->associateDispatchesToDocument($request, $document_id);

 return $res;
 }
 catch(\Illuminate\Validation\ValidationException | \Symfony\Component\HttpKernel\Exception\HttpException $e) { throw $e; }
 catch(Exception $e)
 {
 $this->generalWriteErrorLog($e);

 return $this->generalResponse(false, 'Ocurrió un error: '.$e->getMessage());
 }
 }

 public function validationOpenCash($request)
 {
 // busca una caja chica en el array de pagos
 $find_cash = array_search('cash', array_column($request->payments ?? [],'payment_destination_id'), true);
 // si ha seleccionado una caja chica
 if($find_cash !== false) {
 // no hay id de la caja seleccionada por lo que si es abierta una nueva será seleccionada como destino
 $cash = Cash::where([['user_id', auth()->user()->id],['state', true]])->first();
 if(!$cash){
 return false;
 }
 }
 return true;
 }


